def transform(grid):
    separator = 2
    h, w = len(grid), len(grid[0])

    def bands(length, is_separator):
        result = []
        start = 0
        for i in range(length):
            if is_separator(i):
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_bands = bands(h, lambda r: all(v == separator for v in grid[r]))
    col_bands = bands(w, lambda c: all(grid[r][c] == separator for r in range(h)))

    counts = {}
    for row in grid:
        for v in row:
            if v != separator:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = min(counts, key=counts.get)

    return [
        [
            1 if sum(grid[r][c] == marker
                     for r in range(r0, r1)
                     for c in range(c0, c1)) == 2 else background
            for c0, c1 in col_bands
        ]
        for r0, r1 in row_bands
    ]
